DO $$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.save_activity_plan(uuid,date,jsonb,uuid,boolean)'::regprocedure) INTO f; f:=replace(f,'id uuid;key uuid','new_id uuid;key uuid');f:=replace(f,'id:=gen_random_uuid(); INSERT','new_id:=gen_random_uuid(); INSERT');f:=replace(f,'VALUES(id,_cp','VALUES(new_id,_cp');f:=replace(f,'coalesce(oldp.family_id,id)','coalesce(oldp.family_id,new_id)');EXECUTE f; END $$;